def poblar_base_datos():
    db = SessionLocal()
    try:
        db.add_all(preguntas_entretenimiento)
        db.commit()
        print(f"Se insertaron {len(preguntas_entretenimiento)} preguntas de Entretenimiento correctamente.")
    except Exception as e:
        db.rollback()
        print(f"Error al insertar: {e}")
    finally:
        db.close()

if __name__ == "__main__":
    poblar_base_datos()